ia.com/t/ZS9UEbjUhcQ64-QaY9c/","type":"BARU","noCart":false},{"day":"SABTU","account":"HASBI DECOR","shop":"HASBI DECOR","product":"KALIGRAFI 1SET ISI 3","link":"https://vt.tokopedia.com/t/ZS9UE7GCB318K-kNTk8/","type":"WINNING","noCart":false},{"day":"SABTU","account":"META","shop":"META","product":"EMBLEM RGULER","link":"KIRIM TELE YAZID","type":"WINNING","noCart":false,"telegram":true},{"day":"SABTU","account":"KASIBO","shop":"ZEUS MODIFY","product":"HASIL KERINGAT SENDIRI","link":"https://vt.tokopedia.com/t/ZS9UEvy4RJy2x-SC0Vp/","type":"REGULER","noCart":false},{"day":"SABTU","account":"KASIBO","shop":"ZEUS MODIFY","product":"FCK YOU","link":"https://vt.tokopedia.com/t/ZS9UEvALL865R-vrUXh/","type":"REGULER","noCart":false}];
const days=['SENIN','SELASA','RABU','KAMIS','JUMAT','SABTU'];
const dates={'SENIN':'26 Oktober 2026','SELASA':'27 Oktober 2026','RABU':'28 Oktober 2026','KAMIS':'29 Oktober 2026','JUMAT':'30 Oktober 2026','SABTU':'31 Oktober 2026'};
const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function displayLink(v){if(!v)return '<span class="empty">—</span>';if(/^https:\/\/vt\.tokopedia\.com\/t\/[\w-]+\/$/.test(v))return `<a class="link" href="${esc(v)}" target="_blank" rel="noopener noreferrer">Buka link produk ↗</a>`;return `<span class="instruction">${esc(v)}</span>`;}
document.getElementById('schedule').innerHTML=days.map(day=>{const rows=records.filter(r=>r.day===day);return `<section class="day"><h2>${day.charAt(0)+day.slice(1).toLowerCase()} · ${dates[day]}</h2><div class="table-wrap"><table><thead><tr><th>No.</th><th>Akun TikTok</th><th>Toko Shopee</th><th>Produk</th><th>Link Produk / Catatan</th><th>Jenis Konten</th><th>Upload TikTok</th></tr></thead><tbody>${rows.map((r,i)=>`<tr class="${r.telegram?'telegram':r.noCart?'without':'with'}"><td>${i+1}</td><td>${esc(r.account)}</td><td>${esc(r.shop)}</td><td class="product">${esc(r.product)}</td><td>${displayLink(r.link)}</td><td><span class="type ${r.type.toLowerCase()}">${r.type==='BARU'?'PRODUK BARU':esc(r.type)}</span></td><td class="rule">${r.telegram?'Tidak upload marketplace':r.noCart?'Tanpa keranjang kuning':r.type==='REGULER'?'Bebas (pakai / tanpa keranjang)':'Pakai keranjang kuning'}</td></tr>`).join('')}</tbody></table></div></section>`}).join('');
